CREATE TABLE standard_route_transport(offer_id TEXT PRIMARY KEY REFERENCES route_offers(id),authorization_number TEXT NOT NULL DEFAULT '',frequency_reference TEXT NOT NULL DEFAULT '',features TEXT NOT NULL DEFAULT '');
CREATE TABLE standard_route_stops(offer_id TEXT NOT NULL REFERENCES route_offers(id),position INTEGER NOT NULL CHECK(position BETWEEN 0 AND 15),city TEXT NOT NULL,terminal TEXT NOT NULL DEFAULT '',offset_minutes INTEGER NOT NULL CHECK(offset_minutes>=0),fare_cents INTEGER NOT NULL CHECK(fare_cents>=0),PRIMARY KEY(offer_id,position));
CREATE TABLE standard_departure_stops(departure_id TEXT NOT NULL REFERENCES departures(id),position INTEGER NOT NULL,city TEXT NOT NULL,terminal TEXT NOT NULL DEFAULT '',offset_minutes INTEGER NOT NULL, fare_cents INTEGER NOT NULL,PRIMARY KEY(departure_id,position));
CREATE TRIGGER ground_departure_stops AFTER INSERT ON departures BEGIN INSERT INTO standard_departure_stops SELECT NEW.id,position,city,terminal,offset_minutes,fare_cents FROM standard_route_stops WHERE offer_id=NEW.offer_id; END;
ALTER TABLE seat_claims ADD COLUMN start_stop INTEGER NOT NULL DEFAULT 0 CHECK(start_stop>=0);
ALTER TABLE seat_claims ADD COLUMN end_stop INTEGER NOT NULL DEFAULT 1000 CHECK(end_stop>start_stop);
DROP INDEX uniq_active_seat_per_departure;
CREATE INDEX idx_ground_seat_range ON seat_claims(departure_id,seat_number,status,start_stop,end_stop);
CREATE TRIGGER ground_seat_overlap_insert BEFORE INSERT ON seat_claims WHEN NEW.status IN('held','confirmed') AND EXISTS(SELECT 1 FROM seat_claims s WHERE s.departure_id=NEW.departure_id AND s.seat_number=NEW.seat_number AND s.status IN('held','confirmed') AND s.start_stop<NEW.end_stop AND s.end_stop>NEW.start_stop) BEGIN SELECT RAISE(ABORT,'seat_unavailable'); END;
CREATE TRIGGER ground_seat_overlap_update BEFORE UPDATE OF status,start_stop,end_stop,seat_number,departure_id ON seat_claims WHEN NEW.status IN('held','confirmed') AND EXISTS(SELECT 1 FROM seat_claims s WHERE s.id<>OLD.id AND s.departure_id=NEW.departure_id AND s.seat_number=NEW.seat_number AND s.status IN('held','confirmed') AND s.start_stop<NEW.end_stop AND s.end_stop>NEW.start_stop) BEGIN SELECT RAISE(ABORT,'seat_unavailable'); END;
CREATE TABLE standard_booking_segments(booking_id TEXT PRIMARY KEY REFERENCES bookings(id),boarding_stop INTEGER NOT NULL,alighting_stop INTEGER NOT NULL CHECK(alighting_stop>boarding_stop),origin TEXT NOT NULL,destination TEXT NOT NULL,pickup_point TEXT NOT NULL DEFAULT '',dropoff_point TEXT NOT NULL DEFAULT '',boarding_offset INTEGER NOT NULL DEFAULT 0);
INSERT OR IGNORE INTO schema_migrations(version) VALUES('0036_route_segments');
CREATE TRIGGER ground_seat_segment_scope BEFORE INSERT ON seat_claims WHEN NEW.start_stop<>COALESCE((SELECT boarding_stop FROM standard_booking_segments WHERE booking_id=NEW.booking_id),0) OR NEW.end_stop<>COALESCE((SELECT alighting_stop FROM standard_booking_segments WHERE booking_id=NEW.booking_id),1000) BEGIN SELECT RAISE(ABORT,'seat_unavailable'); END;
